# Static mixtures are the HMM specialization A=I; fit their gradients explicitly.
def fit_static(k,seed,steps=2600,lr=.04):
 rng=np.random.default_rng(seed);flat=y[:96].reshape(-1,16);e=flat[rng.choice(len(flat),k,False)];e=np.maximum(flat.mean(0)+2.5*(e-flat.mean(0)),.002);e/=e.sum(-1,keepdims=True)
 z=[np.log(e),np.eye(k)*30,np.zeros(k)];m=[np.zeros_like(a) for a in z];vv=[a.copy() for a in m]
 for it in range(1,steps+1):
  l,g=objective(x[:96],y[:96],z)
  for j in [0,2]:
   m[j]=.9*m[j]+.1*g[j];vv[j]=.999*vv[j]+.001*g[j]**2;z[j]-=lr*(m[j]/(1-.9**it))/(np.sqrt(vv[j]/(1-.999**it))+1e-8)
 E,A,pi=[softmax(a) for a in z];pt,_=forward(x[:96],E,A,pi);pv,_=forward(x[96:],E,A,pi)
 return kl(y[:96],pt),kl(y[96:],pv),z
